import {skills} from './model.mjs';
import {skillGroups} from './discovery-model.mjs';
import {aiTypes,aiLevels,transitionStrategy,cleanWorkDetails} from './work-context.mjs';

export const workOptions={
  employment:[['unspecified',['暂不说明','Prefer not to say','Tidak dinyatakan']],['employed',['目前在职','Currently employed','Masih bekerja']],['left',['已经离职','No longer employed','Tidak lagi bekerja']],['returning',['准备重返职场','Returning to work','Kembali bekerja']]],
  reason:[['unspecified',['暂不说明','Prefer not to say','Tidak dinyatakan']],['growth',['主动进阶','Career development','Pembangunan kerjaya']],['voluntary',['主动换岗 / 转型','Voluntary change','Perubahan sukarela']],['layoff',['裁员 / 岗位变化','Layoff / role change','Pemberhentian / perubahan peranan']],['return',['结束空档期','End of a career break','Tamat rehat kerjaya']]],
  priority:[['unspecified',['还没确定','Not decided','Belum pasti']],['income',['尽快恢复收入','Income as soon as possible','Pendapatan secepat mungkin']],['parallel',['保留工作并行准备','Prepare while employed','Bersedia sambil bekerja']],['study',['可以留出学习空档','Time available for study','Ada masa untuk belajar']]],
  goal:[['unsure',['先了解可能的方向','Explore possible directions','Teroka arah berpotensi']],['nearby',['优先找相近岗位','Prioritise adjacent roles','Utamakan jawatan berkaitan']],['advance',['在现有领域进阶','Grow in my field','Maju dalam bidang semasa']],['newfield',['考虑进入新领域','Consider a new field','Pertimbangkan bidang baharu']]],
  aiFocus:[['none',['暂不选择','No focus selected','Belum dipilih']],['verification',['结果核验与风险识别','Checking outputs and risks','Semak hasil dan risiko']],['integration',['工具整合 / 工作流','Tool integration / workflows','Integrasi alat / aliran kerja']],['principles',['模型原理与局限','Model principles and limits','Prinsip dan had model']],['algorithms',['算法与技术更新','Algorithms and technical updates','Algoritma dan perkembangan teknikal']]]
};
const select=(c,name,label,options,value)=>`<label class="field">${c.esc(label)}<select name="${name}">${options.map(([id,copy])=>`<option value="${id}" ${id===value?'selected':''}>${c.esc(c.local(copy))}</option>`).join('')}</select></label>`;
export function workContextLabels(c){const context=cleanWorkDetails(c.state.profile).context;return ['employment','reason','goal'].map(key=>workOptions[key].find(([id])=>id===context[key])).filter(([id])=>!['unspecified','unsure'].includes(id)).map(([,copy])=>c.esc(c.local(copy))).join(' · ')}

export function projectIntake(c){
  const {state,t,esc,button}=c;const step=Math.min(2,state.setupStep);const p=state.profile;const details=cleanWorkDetails(p);
  const steps=['workStep0','workStep1','workStep2'];
  const project=`<div class="w-project-fields"><label class="field">${t('previousRole')}<input name="role" maxlength="100" value="${state.profileConfirmed?esc(c.profileRole()):''}" placeholder="${t('rolePlaceholder')}" required></label><label class="field">${t('experience')}<input name="years" type="number" min="0" max="45" value="${state.profileConfirmed?p.years:''}" required></label><label class="field full">${t('projectName')}<input name="projectName" maxlength="100" value="${esc(details.project.name)}" placeholder="${t('projectNamePlaceholder')}" required></label><label class="field full">${t('projectActions')}<textarea name="actions" rows="2" maxlength="1500" placeholder="${t('projectActionsPlaceholder')}" required>${esc(details.project.actions)}</textarea></label><label class="field full">${t('projectResult')}<input name="result" maxlength="300" value="${esc(details.project.result)}" placeholder="${t('projectResultPlaceholder')}"></label></div>`;
  const situation=`<div class="w-project-fields">${['employment','reason','priority','goal'].map(key=>select(c,key,t('context-'+key),workOptions[key],details.context[key])).join('')}<label class="field full">${t('currentConcern')}<textarea name="concern" rows="3" maxlength="300" placeholder="${t('currentConcernPlaceholder')}">${esc(details.context.concern)}</textarea></label></div><p class="w-field-note">${t('contextPrivacy')}</p>`;
  const confirm=`<div class="w-confirm-groups">${skillGroups.map(group=>`<fieldset><legend>${esc(c.local(group.label))}</legend>${group.ids.map(id=>`<label><input type="checkbox" name="skills" value="${id}" ${p.skills.includes(id)?'checked':''}>${esc(c.skillName(id))}</label>`).join('')}</fieldset>`).join('')}</div><details class="w-ai-input"><summary>${t('aiExperienceOptional')}</summary><div class="w-project-fields">${Object.entries(aiTypes).map(([id,label])=>select(c,'ai-'+id,c.local(label),Object.entries(aiLevels),details.aiUsage[id])).join('')}${select(c,'aiFocus',t('aiFocus'),workOptions.aiFocus,p.aiFocus)}</div></details><p class="w-field-note">${t('projectSkillHint')}</p>`;
  return `<main class="d-page w-intake"><aside><span class="d-eyebrow">${t('workProfileLabel')}</span><h1>${t(steps[step])}</h1><p>${t('workStepDesc'+step)}</p><ol class="w-intake-steps">${steps.map((key,i)=>`<li class="${i===step?'active':''}"><b>${i+1}</b>${t(key)}</li>`).join('')}</ol></aside><section class="w-form-card"><form id="discovery-intake-form">${step===0?project:step===1?situation:confirm}<div class="w-form-actions">${step===0?button(t('useSampleShort'),'fill-experience','d-text-button',null,'type="button"'):button(t('backShort'),'intake-back','d-text-button',null,'type="button"')}<button class="primary-button" type="submit">${t(step===0?'continueSituation':step===1?'continueEvidence':'viewMyPaths')}${c.icon('arrow')}</button></div></form></section></main>`;
}

export function projectReport(c,chart){
  const {state,t,esc,button,icon}=c;const p=state.profile;const details=cleanWorkDetails(p);const strategy=transitionStrategy(p);const project=details.project;
  const aiUsed=Object.entries(aiTypes).filter(([id])=>details.aiUsage[id]!=='none');
  return `<main class="d-page w-report"><div class="d-page-heading d-heading-row"><div><h1>${t('strengthsTitle')}</h1><p>${t('strengthsSub')}</p></div>${button(t('editExperience'),'start-profile','primary-button','edit')}</div><section class="w-project-summary"><div><span class="d-eyebrow">${t('projectName')}</span><h2>${esc(project.name||(state.isSample?t('projectSeedName'):t('noProjectYet')))}</h2><p>${esc(project.actions||(state.isSample?t('experienceSeed'):t('addProjectHint')))}</p>${project.result?`<p class="w-project-result"><span>${t('projectResultShort')}</span>${esc(project.result)}</p>`:''}</div><div class="w-context-summary"><span class="d-eyebrow">${t('currentSituation')}</span><strong>${esc(c.local(strategy.title))}</strong><p>${esc(c.local(strategy.description))}</p><small>${workContextLabels(c)}</small>${details.context.concern?`<small>${esc(details.context.concern)}</small>`:''}</div></section><section class="w-evidence-layout"><div class="w-radar-card"><h2>${t('projectEvidence')}</h2>${chart}<p>${t('coverageNote')}</p></div><div class="w-evidence-groups">${skillGroups.map(group=>`<article><h3>${esc(c.local(group.label))}</h3><div>${group.ids.map(id=>`<span class="${p.skills.includes(id)?'confirmed':'unconfirmed'}">${icon(p.skills.includes(id)?'check':'info')}${esc(c.skillName(id))}</span>`).join('')}</div></article>`).join('')}</div></section><section class="w-ai-summary"><h2>${t('aiExperience')}</h2><p>${aiUsed.length?aiUsed.map(([id,label])=>`${esc(c.local(label))} · ${esc(c.local(aiLevels[details.aiUsage[id]]))}`).join('<br>'):t('noAiEvidence')}</p>${details.aiFocus!=='none'?`<small>${t('aiFocus')}：${esc(c.local(workOptions.aiFocus.find(([id])=>id===details.aiFocus)[1]))}</small>`:''}</section><div class="d-page-actions">${button(t('strengthsAction'),'open-directions','primary-button','arrow')}</div></main>`;
}
